func (q *Queries) PurgeInstanceBackupsBelow(ctx context.Context, arg PurgeInstanceBackupsBelowParams) (int64, error) {
	result, err := q.db.Exec(ctx, purgeInstanceBackupsBelow, arg.InstanceID, arg.Below)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const setBackupVerified = `-- name: SetBackupVerified :exec
UPDATE backups SET verified_at = now() WHERE id = $1 AND status = 'succeeded'
`

// Một restore từ bản này đã hoàn tất (§6.3 verified_at: lần kiểm restore gần nhất).
func (q *Queries) SetBackupVerified(ctx context.Context, id uuid.UUID) error {
	_, err := q.db.Exec(ctx, setBackupVerified, id)
	return err
}

const setMembershipHeadscaleUserID = `-- name: SetMembershipHeadscaleUserID :exec
UPDATE tenant_memberships SET headscale_user_id = $1, updated_at = now(), version = version + 1
WHERE id = $2
`

type SetMembershipHeadscaleUserIDParams struct {
	HeadscaleUserID *int64
	ID              uuid.UUID
}

func (q *Queries) SetMembershipHeadscaleUserID(ctx context.Context, arg SetMembershipHeadscaleUserIDParams) error {
	_, err := q.db.Exec(ctx, setMembershipHeadscaleUserID, arg.HeadscaleUserID, arg.ID)
	return err
}
